/**
 * Read-only Flap Token Mode preflight through the locally authenticated Alchemy CLI.
 *
 * Required environment:
 *   FLAP_SALT_FILE  private JSON generated by mine-flap-salt.mjs
 *   TINYAI_WALLETS_ENV private env file containing TINYAI_DEPLOYER_ADDRESS
 *
 * The salt and calldata are never printed. This script never signs or broadcasts.
 */
import { execFile } from "node:child_process";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { promisify } from "node:util";
import {
  concat,
  decodeFunctionResult,
  encodeFunctionData,
  formatEther,
  getAddress,
  getContractAddress,
} from "viem";

const NETWORK = "bnb-mainnet";
const PORTAL = getAddress("0xe2cE6ab80874Fa9Fa2aAE65D277Dd6B8e65C9De0");
const IMPLEMENTATION = getAddress("0x024f18294970B5c76c0691b87f138A0317156422");
const NVDAB = getAddress("0x02Fca66C1D1aFB4E2A7884261eB00F63598a7436");
const BRAIN_REGISTRY = getAddress("0x29EefCC07eA38535A16fe4fB9c9469d4634C1fA1");
const ZERO = "0x0000000000000000000000000000000000000000";
const ZERO_HASH = `0x${"00".repeat(32)}`;
const META = "QmcFiqZScoop6uDjpPzsxTuSkcEZGLs13iZjSHqFqhY2Qy";

const saltFile = process.env.FLAP_SALT_FILE;
const walletsFile = process.env.TINYAI_WALLETS_ENV;
if (!saltFile || !walletsFile) throw new Error("FLAP_SALT_FILE and TINYAI_WALLETS_ENV are required");

const saltRecord = JSON.parse(readFileSync(saltFile, "utf8"));
const wallets = Object.fromEntries(
  readFileSync(walletsFile, "utf8")
    .split(/\r?\n/)
    .filter((line) => line && !line.trimStart().startsWith("#") && line.includes("="))
    .map((line) => {
      const index = line.indexOf("=");
      return [line.slice(0, index).trim(), line.slice(index + 1).trim()];
    }),
);
const deployer = getAddress(wallets.TINYAI_DEPLOYER_ADDRESS);
const expectedToken = getAddress(saltRecord.address);
const salt = saltRecord.salt;

const proxyCreationCode = concat([
  "0x3d602d80600a3d3981f3363d3d373d3d3d363d73",
  IMPLEMENTATION,
  "0x5af43d82803e903d91602b57fd5bf3",
]);
const independentlyPredicted = getContractAddress({
  from: PORTAL,
  salt,
  bytecode: proxyCreationCode,
  opcode: "CREATE2",
});

const portalAbi = [
  {
    type: "function",
    name: "getSaltLock",
    stateMutability: "view",
    inputs: [{ name: "salt", type: "bytes32" }],
    outputs: [{ name: "entry", type: "tuple", components: [{ name: "locker", type: "address" }, { name: "tokenVersion", type: "uint8" }] }],
  },
  {
    type: "function",
    name: "newTokenV6",
    stateMutability: "payable",
    inputs: [{
      name: "params",
      type: "tuple",
      components: [
        { name: "name", type: "string" }, { name: "symbol", type: "string" }, { name: "meta", type: "string" },
        { name: "dexThresh", type: "uint8" }, { name: "salt", type: "bytes32" }, { name: "migratorType", type: "uint8" },
        { name: "quoteToken", type: "address" }, { name: "quoteAmt", type: "uint256" }, { name: "beneficiary", type: "address" },
        { name: "permitData", type: "bytes" }, { name: "extensionID", type: "bytes32" }, { name: "extensionData", type: "bytes" },
        { name: "dexId", type: "uint8" }, { name: "lpFeeProfile", type: "uint8" },
        { name: "buyTaxRate", type: "uint16" }, { name: "sellTaxRate", type: "uint16" },
        { name: "taxDuration", type: "uint64" }, { name: "antiFarmerDuration", type: "uint64" },
        { name: "mktBps", type: "uint16" }, { name: "deflationBps", type: "uint16" },
        { name: "dividendBps", type: "uint16" }, { name: "lpBps", type: "uint16" },
        { name: "minimumShareBalance", type: "uint256" }, { name: "dividendToken", type: "address" },
        { name: "commissionReceiver", type: "address" }, { name: "tokenVersion", type: "uint8" },
      ],
    }],
    outputs: [{ name: "token", type: "address" }],
  },
];

const execFileAsync = promisify(execFile);

async function rpc(method, ...params) {
  const windows = process.platform === "win32";
  const executable = windows ? process.execPath : "alchemy";
  const prefix = windows ? [resolve(process.env.APPDATA, "npm/node_modules/@alchemy/cli/dist/index.js")] : [];
  const { stdout } = await execFileAsync(executable, [...prefix, "--json", "--no-interactive", "evm", "rpc", method, ...params, "-n", NETWORK], {
    encoding: "utf8",
    windowsHide: true,
  });
  return JSON.parse(stdout.trim());
}

const codeEntries = await Promise.all(
  [
    ["predictedToken", expectedToken],
    ["portal", PORTAL],
    ["taxV3Implementation", IMPLEMENTATION],
    ["quoteTokenNVDAB", NVDAB],
    ["brainRegistry", BRAIN_REGISTRY],
  ].map(async ([label, address]) => [label, await rpc("eth_getCode", address, "latest")]),
);
const codes = Object.fromEntries(codeEntries);

const lockCall = encodeFunctionData({ abi: portalAbi, functionName: "getSaltLock", args: [salt] });
const launchParams = {
  name: "TinyAI",
  symbol: "TINYAI",
  meta: META,
  dexThresh: 1,
  salt,
  migratorType: 1,
  quoteToken: NVDAB,
  quoteAmt: 0n,
  beneficiary: deployer,
  permitData: "0x",
  extensionID: ZERO_HASH,
  extensionData: "0x",
  dexId: 0,
  lpFeeProfile: 0,
  buyTaxRate: 100,
  sellTaxRate: 100,
  taxDuration: 2_592_000n,
  antiFarmerDuration: 0n,
  mktBps: 10_000,
  deflationBps: 0,
  dividendBps: 0,
  lpBps: 0,
  minimumShareBalance: 0n,
  dividendToken: NVDAB,
  commissionReceiver: ZERO,
  tokenVersion: 6,
};
const launchCall = encodeFunctionData({ abi: portalAbi, functionName: "newTokenV6", args: [launchParams] });
const [lockRaw, simulationRaw, latestNonceRaw, pendingNonceRaw, balanceRaw, blockRaw] = await Promise.all([
  rpc("eth_call", JSON.stringify({ to: PORTAL, data: lockCall }), "latest"),
  rpc("eth_call", JSON.stringify({ from: deployer, to: PORTAL, data: launchCall, value: "0x3b9aca00" }), "latest"),
  rpc("eth_getTransactionCount", deployer, "latest"),
  rpc("eth_getTransactionCount", deployer, "pending"),
  rpc("eth_getBalance", deployer, "latest"),
  rpc("eth_blockNumber"),
]);
const lock = decodeFunctionResult({ abi: portalAbi, functionName: "getSaltLock", data: lockRaw });
const simulatedToken = getAddress(decodeFunctionResult({ abi: portalAbi, functionName: "newTokenV6", data: simulationRaw }));

const latestNonce = BigInt(latestNonceRaw);
const pendingNonce = BigInt(pendingNonceRaw);
const balance = BigInt(balanceRaw);
const block = BigInt(blockRaw);

const checks = {
  predictedAddressEnds7777: expectedToken.toLowerCase().endsWith("7777"),
  independentPredictionMatches: independentlyPredicted === expectedToken,
  predictedAddressEmpty: codes.predictedToken === "0x",
  portalHasCode: codes.portal !== "0x",
  taxV3ImplementationHasCode: codes.taxV3Implementation !== "0x",
  quoteTokenHasCode: codes.quoteTokenNVDAB !== "0x",
  brainRegistryHasCode: codes.brainRegistry !== "0x",
  unlockedSaltEntryEmpty: lock.locker === ZERO && Number(lock.tokenVersion) === 0,
  launchSimulationMatches: simulatedToken === expectedToken,
};
if (Object.values(checks).some((value) => value !== true)) throw new Error(`preflight failed: ${JSON.stringify(checks)}`);

console.log(JSON.stringify({
  chainId: 56,
  block: block.toString(),
  deployer,
  balanceBnb: formatEther(balance),
  latestNonce: latestNonce.toString(),
  pendingNonce: pendingNonce.toString(),
  expectedToken,
  metadataCid: META,
  tax: { buyBps: 100, sellBps: 100, durationSeconds: 2_592_000 },
  saltLock: "empty-unlocked",
  checks,
  signed: false,
  broadcast: false,
}, null, 2));
